#!/usr/bin/env node
/**
 * Single source for the vehicle image registry.
 *
 * `services/vehicle-image-catalog.json` (this repository) is the only file anyone
 * edits. The Mator backend embeds it byte for byte in
 * `src/garage/vehicle-images/vehicle-image-catalog.data.ts`, generated by this
 * script. Both components derive SHA-256 from those bytes at run time; no
 * separately maintained hash can conceal a stale registry. The pipeline reports
 * the fingerprint it loaded and the backend refuses answers from another version.
 *
 *   node scripts/vehicle-image-registry-sync.mjs --backend ../mator.uz/Backend          write
 *   node scripts/vehicle-image-registry-sync.mjs --backend ../mator.uz/Backend --check  verify only
 *
 * The registry must be committed first: the generated header names the commit.
 */
import { execFileSync } from 'node:child_process';
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { registryFingerprint } from '../services/vehicle-image-registry.mjs';

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const registryFile = path.join(repoRoot, 'services/vehicle-image-catalog.json');
const target = 'src/garage/vehicle-images/vehicle-image-catalog.data.ts';

function fail(message) {
  console.error(`registry sync refused: ${message}`);
  process.exit(1);
}

const args = process.argv.slice(2);
const backendIndex = args.indexOf('--backend');
const backend = backendIndex >= 0 ? args[backendIndex + 1] : null;
const check = args.includes('--check');
if (!backend) fail('pass --backend <path to the Mator Backend directory>');
const backendDir = path.resolve(backend);
if (!existsSync(path.join(backendDir, 'src/garage/vehicle-images'))) fail(`${backendDir} is not the Mator Backend`);

const bytes = readFileSync(registryFile);
const text = bytes.toString('utf8');
if (text.includes('`') || text.includes('${') || text.includes('\r'))
  fail('the registry contains a backtick, "${" or a carriage return and cannot be embedded verbatim');
JSON.parse(text);
const sha256 = registryFingerprint(bytes);

const git = (...gitArgs) => execFileSync('git', gitArgs, { cwd: repoRoot, encoding: 'utf8' }).trim();
if (git('status', '--porcelain', '--', 'services/vehicle-image-catalog.json'))
  fail('commit services/vehicle-image-catalog.json first; the generated file names its commit');
const commit = git('log', '-1', '--format=%H', '--', 'services/vehicle-image-catalog.json');

const generated = `/**
 * The vehicle image registry, byte for byte. GENERATED: do not edit.
 *
 * Source: MatorUI- \`services/vehicle-image-catalog.json\` at commit
 * ${commit}, written by MatorUI- \`scripts/vehicle-image-registry-sync.mjs\`.
 * The Vehicle Image Pipeline loads the same file and reports its SHA-256; the
 * backend refuses pipeline answers computed from any other registry. Data only:
 * the rules that read it are in vehicle-image.catalog.ts.
 */
import { createHash } from 'node:crypto';

export const VEHICLE_IMAGE_CATALOG_SOURCE = String.raw\`${text}\`;

export const VEHICLE_IMAGE_CATALOG_SHA256 = createHash('sha256')
  .update(VEHICLE_IMAGE_CATALOG_SOURCE)
  .digest('hex');
`;

const targetFile = path.join(backendDir, target);
const current = existsSync(targetFile) ? readFileSync(targetFile, 'utf8') : '';
if (check) {
  // Check the generated source itself, not a checksum declaration that could be
  // left unchanged while the embedded mappings drift.
  if (current !== generated)
    fail('backend registry source or provenance differs; regenerate it from this committed canonical registry');
  console.log(`backend registry matches ${sha256}`);
} else {
  writeFileSync(targetFile, generated);
  console.log(`wrote ${target} (registry ${sha256}, commit ${commit.slice(0, 12)})`);
}
